327	static const lv_point_precise_t *PTS(const lv_point_precise_t *src, int n)
328	{
329	    if (s_pts_n + n > PTS_POOL_MAX) {
330	        s_pts_n = 0;
331	    }
332	    memcpy(&s_pts_pool[s_pts_n], src, (size_t)n * sizeof(s_pts_pool[0]));
333	    {
334	        const lv_point_precise_t *p = &s_pts_pool[s_pts_n];
335	
336	        s_pts_n += n;
337	        return p;
338	    }
339	}
