626	static void dial_tick_layout(int cx, int cy, int d)
627	{
628	    for (int i = 0; i < 24; i++) {
629	        const int deg = i * 15;
630	        const bool major = (i % 6 == 0);
631	        const double a = (double)deg * DEG2RAD;
632	        const double r1 = (major ? 66.0 : 69.0) * (double)d / 160.0;
633	        const double r2 = 74.0 * (double)d / 160.0;
634	
635	        UD.tick_pts[i][0].x = cx + (int)lround(sin(a) * r1);
636	        UD.tick_pts[i][0].y = cy - (int)lround(cos(a) * r1);
637	        UD.tick_pts[i][1].x = cx + (int)lround(sin(a) * r2);
638	        UD.tick_pts[i][1].y = cy - (int)lround(cos(a) * r2);
639	        if (UD.tick[i] != NULL) {
640	            lv_line_set_points(UD.tick[i], UD.tick_pts[i], 2);
641	        }
642	    }
643	}
644	
645	static void dial_pointer_layout(int angle)
646	{
647	    const double a = (double)angle * DEG2RAD;
648	    const double sx = sin(a);
649	    const double sy = -cos(a);
650	    const double px = cos(a);
651	    const double py = sin(a);
652	    const double sc = (double)UD.d / 160.0;
653	    const double r0 = 56.0 * sc;
654	    const double r1 = 84.0 * sc;
655	    const int x0 = UD.cx + (int)lround(sx * r0);
656	    const int y0 = UD.cy + (int)lround(sy * r0);
657	    const int x1 = UD.cx + (int)lround(sx * r1);
658	    const int y1 = UD.cy + (int)lround(sy * r1);
659	    const int cw = (int)lround(8.0 * sc);
660	
661	    UD.ptr_pts[0].x = x0;
662	    UD.ptr_pts[0].y = y0;
663	    UD.ptr_pts[1].x = x1;
664	    UD.ptr_pts[1].y = y1;
665	    UD.cross_pts[0].x = x1 - (int)lround(px * cw);
666	    UD.cross_pts[0].y = y1 - (int)lround(py * cw);
667	    UD.cross_pts[1].x = x1 + (int)lround(px * cw);
668	    UD.cross_pts[1].y = y1 + (int)lround(py * cw);
669	    if (UD.ptr != NULL) {
670	        lv_line_set_points(UD.ptr, UD.ptr_pts, 2);
671	    }
672	    if (UD.cross != NULL) {
673	        lv_line_set_points(UD.cross, UD.cross_pts, 2);
674	    }
675	}
