822	    UD.ring = RING(s_scr, UD.cx, UD.cy, 160, 2, P_TRACK);
823	    dial_sector(s_mode, LV_OPA_COVER, &UD.fill, &UD.trk);
824	
825	    /* 24 刻度：每 15°，整点 3px。 */
