832	    /* 舵柄：中心到外圈 + 8px 横杆。 */
833	    UD.ptr = LINE(s_scr, UD.ptr_pts, 2, 3, P_INK);
834	    UD.cross = LINE(s_scr, UD.cross_pts, 2, 3, P_INK);
