930	static void rot_exec(void *var, int32_t p)
931	{
932	    (void)var;
933	    s_angle = s_rot_a0 + (s_rot_a1 - s_rot_a0) * (int)p / 1000;
934	    UD.angle = s_angle;
935	    dial_pointer_layout(s_angle);
936	    s_rot_oa_cur = s_rot_oa0 * (1000 - (int)p) / 1000;
937	    s_rot_ob_cur = s_rot_ob0 + (255 - s_rot_ob0) * (int)p / 1000;
938	    SET_ARC_OPA(UD.fill, s_rot_oa_cur);
939	    SET_ARC_OPA(UD.trk, s_rot_oa_cur);
940	    SET_ARC_OPA(UD.fill2, s_rot_ob_cur);
941	    SET_ARC_OPA(UD.trk2, s_rot_ob_cur);
942	    if (!s_rot_swapped && p >= 500) {
943	        s_rot_swapped = true;
944	        dial_content(s_rot_to_mode);
945	    }
946	}
