948	static void rot_ready(lv_anim_t *a)
949	{
950	    (void)a;
951	    s_rot_anim = NULL;
952	    if (UD.fill != NULL) {
953	        lv_obj_delete(UD.fill);
954	        lv_obj_delete(UD.trk);
955	    }
956	    UD.fill = UD.fill2;
957	    UD.trk = UD.trk2;
958	    UD.fill2 = NULL;
