976	static void dial_rotate_next(void)
977	{
978	    int from_mode;
979	    int to_mode;
980	    int a0;
981	    int target;
982	    int duration = 160;
983	    lv_anim_t a;
984	
985	    /* 转场中禁止再转；但盘面旋转本身可以被下一次 KEY1 打断（#2）。 */
986	    if (UD.fill == NULL || (s_busy && s_tr_anim != NULL)) {
987	        return;
988	    }
989	    a0 = (int)s_angle;
990	
991	    if (s_rot_anim != NULL) {
992	        /* ANIMATION #2：从当前角重定目标，120ms；旧 B 升为 A。 */
993	        lv_anim_delete(&s_rot_p, NULL);
994	        s_rot_anim = NULL;
995	        if (UD.fill != NULL) {
996	            lv_obj_delete(UD.fill);
997	            lv_obj_delete(UD.trk);
998	        }
999	        UD.fill = UD.fill2;
1000	        UD.trk = UD.trk2;
1001	        UD.fill2 = NULL;
1002	        UD.trk2 = NULL;
1003	        from_mode = s_rot_to_mode;
1004	        s_rot_oa0 = s_rot_oa_cur;
1005	        s_rot_ob0 = s_rot_ob_cur;
1006	        s_mode = from_mode;
1007	        duration = 120;
1008	    } else {
1009	        from_mode = s_mode;
1010	        s_rot_oa0 = 255;
1011	        s_rot_ob0 = 0;
1012	    }
1013	    s_rot_oa_cur = s_rot_oa0;
1014	    s_rot_ob_cur = s_rot_ob0;
1015	    to_mode = (from_mode + 1) % M_COUNT;
1016	
1017	    target = to_mode * 90;
1018	    while (target <= a0) {
1019	        target += 360;
1020	    }
1021	
1022	    s_rot_a0 = a0;
1023	    s_rot_a1 = target;
1024	    s_rot_from_mode = from_mode;
1025	    s_rot_to_mode = to_mode;
1026	    s_rot_swapped = false;
1027	    dial_sector(to_mode, (lv_opa_t)s_rot_ob0, &UD.fill2, &UD.trk2);
1028	    {
1029	        char buf[24];
1030	
1031	        snprintf(buf, sizeof(buf), "%02d → %02d", s_shown_mode + 1,
1032	                 to_mode + 1);
1033	        lv_label_set_text(UD.top_r, buf);
1034	    }
1035	
1036	    s_busy = true;
1037	    lv_anim_init(&a);
1038	    lv_anim_set_var(&a, &s_rot_p);
1039	    lv_anim_set_values(&a, 0, 1000);
1040	    lv_anim_set_duration(&a, duration);
1041	    lv_anim_set_path_cb(&a, lv_anim_path_ease_in_out);
1042	    lv_anim_set_exec_cb(&a, rot_exec);
1043	    lv_anim_set_ready_cb(&a, rot_ready);
1044	    s_rot_anim = lv_anim_start(&a);
1045	}
