2519	static void ui_tick(lv_timer_t *t)
2520	{
2521	    (void)t;
2522	    for (;;) {
2523	        int key = 0;
2524	        bool down = false;
2525	
2526	        if (!sim_display_take_key_event(&key, &down)) {
2527	            break;
2528	        }
2529	        if (s_busy) {
2530	            const bool dial_rot =
2531	                (s_screen == SCR_DIAL && s_tr_anim == NULL && s_rot_anim != NULL);
2532	
2533	            if (!(dial_rot && key == 1)) {
2534	                continue;
2535	            }
2536	        }
2537	        if (down) {
2538	            if (LP.active) {
2539	                continue;
2540	            }
2541	            if ((key == 1 && screen_has_lp1()) ||
2542	                (key == 2 && screen_has_lp2())) {
2543	                lp_begin(key);
2544	            } else {
2545	                do_short(key);
2546	            }
2547	        } else {
2548	            if (LP.active && LP.key == key) {
2549	                const uint32_t held = lv_tick_get() - LP.t0;
2550	
2551	                if (held < 160) {
2552	                    LP.active = false;
2553	                    lp_ui_clear();
2554	                    if (s_screen == SCR_DIAL) {
2555	                        dial_content(s_mode);
2556	                    }
2557	                    if (s_legend != NULL) {
2558	                        lv_label_set_text(s_legend, s_legend_base);
2559	                    }
2560	                    do_short(key);
2561	                } else {
2562	                    lp_cancel();
2563	                }
2564	            }
2565	        }
2566	    }
2567	    lp_tick();
2568	    if (s_toast_until != 0 && lv_tick_get() > s_toast_until) {
2569	        s_toast_until = 0;
2570	        if (s_legend != NULL && !LP.active) {
2571	            lv_label_set_text(s_legend, s_legend_base);
2572	        }
2573	    }
2574	    tour_tick();
2575	}
